import data.glitch_lib

Glitch_Analysis[result] {
    # Gather all unit blocks from the project
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find all conditional statements within the unit block
    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    # Check if the conditional is a SWITCH type (covers switch, case, match)
    cond.type == "SWITCH"

    # Traverse the else_statement chain to find if there's a default case
    has_default := false
    current := cond
    while {
        current.is_default == true {
            has_default := true
            break
        }
        current.else_statement != null {
            current := current.else_statement
        }
        current.else_statement == null {
            break
        }
    }

    # If no default case is found in the entire chain, flag it
    not has_default

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in switch-like conditional (CWE-478). This can lead to unhandled states and undefined behavior in IaC."
    }
}

